int hour = 22;

if (hour >= 0 && hour < 12) {
    System.out.println("Bom dia"); // 0h até 11h59
} else if (hour >= 12 && hour < 18) {
    System.out.println("Boa tarde"); // 12h até 17h59
} else if (hour >= 18 && hour <= 24) {
    System.out.println("Boa noite"); // 18h até 24h
} else {
    System.out.println("Hora inválida"); // qualquer valor fora de 0-24
}

